import BigNumber from "bignumber.js";
import { LengthGreaterThanMaxError, LengthNotNumericError } from "../ValidationErrors";
import type { ValidatedNEA } from "../Validated";
/**
 * Creates a validator that validates that the object passed
 * in with a length value has a length value that is
 * the maximum length or less than the maximum length.
 *
 * @internal
 */
export declare const maxLength: (maxLen: number | bigint | BigNumber) => <L extends {
    length: number | bigint | BigNumber;
}>(value: L) => ValidatedNEA<LengthNotNumericError | LengthGreaterThanMaxError<number | bigint | BigNumber>, L>;
